<script setup>import {onMounted,reactive,ref} from 'vue';import api from '../api';import {useAuthStore} from '../stores/auth';import {ElMessage} from 'element-plus';const auth=useAuthStore(),list=ref([]),keyword=ref(''),visible=ref(false),editing=ref(false);const empty=()=>({name:'',location:'',capacity:40,manager:'',phone:'',description:'',openTime:'08:00',closeTime:'21:00',openStatus:1});const form=reactive(empty());async function load(){list.value=(await api.get('/labs',{params:{keyword:keyword.value||undefined}})).data}function open(row){Object.assign(form,row||empty());editing.value=!!row;visible.value=true}async function save(){if(editing.value)await api.put(`/manage/labs/${form.id}`,form);else await api.post('/manage/labs',form);ElMessage.success('保存成功');visible.value=false;await load()}onMounted(load);</script>
<template><div class="page"><div class="page-head"><div><h2 class="page-title">实验室管理</h2><div class="page-sub">查询实验室的位置、容量和开放状态</div></div><el-button v-if="auth.isSystemAdmin" type="primary" @click="open()"><Plus/>新增实验室</el-button></div><div class="panel"><div class="toolbar"><el-input v-model="keyword" clearable placeholder="搜索名称或位置" style="width:280px" @keyup.enter="load"><template #prefix><Search/></template></el-input><el-button @click="load">查询</el-button></div><el-table :data="list"><el-table-column prop="name" label="实验室" min-width="170"><template #default="s"><b>{{s.row.name}}</b><div class="minor">{{s.row.description}}</div></template></el-table-column><el-table-column prop="location" label="位置" width="150"/><el-table-column prop="capacity" label="容量" width="100"><template #default="s">{{s.row.capacity}}人</template></el-table-column><el-table-column label="开放时间" width="160"><template #default="s">{{s.row.openTime}} - {{s.row.closeTime}}</template></el-table-column><el-table-column prop="manager" label="负责人" width="110"/><el-table-column label="状态" width="100"><template #default="s"><el-tag :type="s.row.openStatus?'success':'info'">{{s.row.openStatus?'开放':'停用'}}</el-tag></template></el-table-column><el-table-column v-if="auth.isManager" label="操作" width="90"><template #default="s"><el-button link type="primary" @click="open(s.row)">编辑</el-button></template></el-table-column></el-table></div><el-dialog v-model="visible" :title="editing?'编辑实验室':'新增实验室'" width="600"><el-form :model="form" label-width="90px"><el-row :gutter="16"><el-col :span="12"><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item></el-col><el-col :span="12"><el-form-item label="位置"><el-input v-model="form.location"/></el-form-item></el-col><el-col :span="12"><el-form-item label="容量"><el-input-number v-model="form.capacity" :min="1" style="width:100%"/></el-form-item></el-col><el-col :span="12"><el-form-item label="负责人"><el-input v-model="form.manager"/></el-form-item></el-col><el-col :span="12"><el-form-item label="开放时间"><el-time-select v-model="form.openTime" start="07:00" step="00:30" end="22:00"/></el-form-item></el-col><el-col :span="12"><el-form-item label="关闭时间"><el-time-select v-model="form.closeTime" start="08:00" step="00:30" end="23:00"/></el-form-item></el-col><el-col :span="24"><el-form-item label="简介"><el-input v-model="form.description" type="textarea"/></el-form-item></el-col></el-row></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<style scoped>.minor{font-size:12px;color:#91a2a7;margin-top:5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}</style>
